<?php require dirname(__DIR__).'/inc/page_helpers.php';login_required();if(page_post()){check_csrf();$title=trim((string)($_POST['title']??''));$description=trim((string)($_POST['description']??''));if($title===''){notice('A place name is required.','error');go('/My/CreatePlace.php');}$q=$db->prepare('INSERT INTO games(creator_id,title,description) VALUES(?,?,?)');$q->execute([$currentUser['id'],$title,$description]);notice('Place created.');go('/PlaceItem.php?id='.$db->lastInsertId());}page_start('Create Place');?><section class="Panel"><h1>Create a Place</h1><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><label>Place name<input name="title" maxlength="120" required></label><label>Description<textarea name="description" rows="5"></textarea></label><button class="Button">Create Place</button></form><p>This creates a place listing; uploading and running a legacy game build is a separate feature.</p></section><?php page_end();